<script setup>
import { ref, onMounted, nextTick, watch } from 'vue';
import { getToken, knowledgeStatus, askJobKnowledge, searchJobKnowledge, getPositionFollows, addPositionFollow, removePositionFollow } from '../api';
const emit = defineEmits(['require-login','follow-changed','open-link']);
const props=defineProps({active:Boolean});
watch(()=>props.active,async active=>{if(!active||!getToken())return;try{const ids=new Set((await getPositionFollows()).map(row=>Number(row.positionId)));for(const turn of turns.value)for(const job of turn.jobs||[])job.isFavorite=ids.has(Number(job.positionId));}catch(e){error.value=e.message;}});
const draft=ref(''), turns=ref([]), loading=ref(false), error=ref(''), coverage=ref(null), messages=ref(null);
const pageLoading=ref(false);
const favoriteBusy=ref(new Set());
const examples=['找一下产品经理相关岗位','有哪些明确专业不限的岗位？','找一下计算机相关岗位','哪些岗位提供住宿或餐补？'];
const safeUrl = value => { try {const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';} catch {return '';} };
const list = value => Array.isArray(value) ? value.join('、') : (typeof value==='string'?value:'');
async function refreshStatus(){
 if(!getToken())return;
 try {coverage.value=await knowledgeStatus();} catch(e){error.value=e.message;}
}
onMounted(refreshStatus);
async function send(text){
 if(loading.value)return;
 if(!getToken()){emit('require-login');return;}
 const question=String(text || draft.value).trim();if(!question)return;
 const history=turns.value.slice(-6).map(t=>({role:t.role,content:t.content}));
 turns.value.push({role:'user',content:question});draft.value='';loading.value=true;error.value='';
 try {
  const data=await askJobKnowledge({message:question,history});
  coverage.value=data.coverage;
  const favorites=await getPositionFollows();const favoriteIds=new Set((favorites||[]).map(job=>Number(job.positionId)));
  const jobs=(data.jobs||[]).map(job=>({...job,isFavorite:favoriteIds.has(Number(job.positionId))}));
  turns.value.push({role:'assistant',content:data.summary,jobs,filters:data.filters,total:data.total,page:data.page,pageInput:data.page,totalPages:data.totalPages,pageSize:data.pageSize});
 } catch(e){error.value=e.message;draft.value=question;turns.value.pop();}
 finally {loading.value=false;await nextTick();messages.value?.lastElementChild?.scrollIntoView({behavior:'smooth',block:'start'});}
}
async function changePage(turn,page){const requested=Number(page);if(pageLoading.value||loading.value||!Number.isInteger(requested)||requested<1||requested>turn.totalPages)return;pageLoading.value=true;error.value='';try{const data=await searchJobKnowledge({filters:turn.filters,page:requested});const favorites=await getPositionFollows();const favoriteIds=new Set((favorites||[]).map(job=>Number(job.positionId)));Object.assign(turn,{jobs:(data.jobs||[]).map(job=>({...job,isFavorite:favoriteIds.has(Number(job.positionId))})),page:data.page,pageInput:data.page,total:data.total,totalPages:data.totalPages});await nextTick();messages.value?.querySelectorAll('.kb-assistant')[turns.value.filter(t=>t.role==='assistant').indexOf(turn)]?.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){error.value=e.message;}finally{pageLoading.value=false;}}
async function toggleFavorite(job){if(favoriteBusy.value.has(job.positionId))return;favoriteBusy.value=new Set(favoriteBusy.value).add(job.positionId);try{if(job.isFavorite)await removePositionFollow(job.positionId);else await addPositionFollow(job.positionId);const isFavorite=!job.isFavorite;for(const turn of turns.value)for(const row of turn.jobs||[])if(Number(row.positionId)===Number(job.positionId))row.isFavorite=isFavorite;emit('follow-changed');}catch(e){error.value=e.message;}finally{const busy=new Set(favoriteBusy.value);busy.delete(job.positionId);favoriteBusy.value=busy;}}
function clear(){if(!loading.value){turns.value=[];error.value='';}}
</script>
<template>
 <section class="kb-chat">
  <header class="kb-head"><div><span class="kb-eyebrow">公告知识库 · 全库检索</span><h1>AI 找岗位</h1></div><button class="kb-secondary" :disabled="loading" @click="clear">新对话</button></header>
  <div v-if="!turns.length" class="kb-welcome"><div class="kb-spark">✦</div><h2>聊一聊，找到你的下一站</h2><p>从专业、城市到岗位方向，把你的想法告诉我。</p><div class="kb-examples"><button v-for="q in examples" :key="q" @click="send(q)">{{q}} <span>↗</span></button></div></div>
  <div ref="messages" class="kb-messages" aria-live="polite">
   <article v-for="(turn,index) in turns" :key="index" :class="['kb-turn','kb-'+turn.role]">
    <template v-if="turn.role==='user'"><div class="kb-user-bubble">{{turn.content}}</div></template>
    <template v-else>
     <div class="kb-answer-label">✦ 公告检索结果</div><div class="kb-summary">{{turn.content}}</div><p class="kb-review-note">岗位信息均为人工整理，需以官方信息复核学历、专业、城市等条件</p>
     <div class="kb-result-count">全库符合条件的岗位 <strong>{{turn.total || 0}}</strong> 条</div>
     <div v-if="!turn.jobs?.length" class="kb-empty">全量检索的候选岗位中没有找到匹配项，可以减少条件或更换关键词。</div>
     <div class="kb-results"><div v-for="job in turn.jobs" :key="job.positionId" class="kb-job">
      <div class="kb-job-heading"><div class="kb-job-identity"><h3>{{job.title}}</h3><div class="kb-company-line"><strong>{{job.companyName}}</strong><div class="kb-company-meta"><span>{{job.companyNature || job.companyNatureRaw || '企业类型未说明'}}</span><span v-if="job.industry">{{job.industry}}</span><span v-if="job.recruitTypes">{{job.recruitTypes}}</span></div></div></div><div class="kb-deadline"><span>网申截止</span><strong>{{job.deadlineDate || job.deadline || job.campaign.deadline || '公告未说明'}}</strong></div></div>
      <div class="kb-tags"><span v-if="list(job.facts.cities)">{{list(job.facts.cities)}}</span><span v-if="job.facts.education">{{job.facts.education}}</span><span v-if="job.facts.graduation">{{job.facts.graduation}}</span></div>
      <dl><div><dt>专业要求</dt><dd>{{job.facts.majorRaw || '公告未说明'}}</dd></div><div v-if="job.facts.requirements"><dt>任职要求</dt><dd>{{job.facts.requirements}}</dd></div><div v-if="job.facts.salary"><dt>薪资待遇</dt><dd>{{job.facts.salary}}</dd></div><div v-if="job.facts.headcount"><dt>招聘人数</dt><dd>{{job.facts.headcount}}</dd></div><div v-if="job.facts.responsibilities"><dt>岗位职责</dt><dd>{{job.facts.responsibilities}}</dd></div><div v-if="job.facts.benefits || job.campaign.benefits"><dt>福利待遇</dt><dd>{{job.facts.benefits || job.campaign.benefits}}<small v-if="!job.facts.benefits">（招聘批次公共说明）</small></dd></div></dl>
      <details><summary>查看公告依据与公司介绍</summary><p v-if="job.companyIntroduction">{{job.companyIntroduction}}</p><p v-if="job.facts.evidence">岗位依据：{{job.facts.evidence}}</p><p>公告：{{job.documentTitle}}</p></details>
      <footer><span class="kb-updated">更新时间：{{(job.updatedAt || job.retrievedAt || '').slice(0,10) || '未提供'}}</span><a v-if="safeUrl(job.noticeUrl || job.sourceUrl)" :href="safeUrl(job.noticeUrl || job.sourceUrl)" target="_blank" rel="noopener noreferrer" @click.prevent="emit('open-link',safeUrl(job.noticeUrl || job.sourceUrl))">查看网申公告 ↗</a><span v-else class="kb-link-disabled">暂无网申公告</span><a v-if="safeUrl(job.applyUrl)" class="kb-apply-button" :href="safeUrl(job.applyUrl)" target="_blank" rel="noopener noreferrer" @click.prevent="emit('open-link',safeUrl(job.applyUrl))">投递地址 ↗</a><span v-else class="kb-link-disabled">暂无投递地址</span><button class="kb-favorite-button" :class="{active:job.isFavorite}" :disabled="favoriteBusy.has(job.positionId)" @click="toggleFavorite(job)">{{favoriteBusy.has(job.positionId)?'处理中…':job.isFavorite?'已关注':'关注'}}</button></footer>
     </div></div><nav v-if="turn.totalPages>1" class="kb-pagination" aria-label="岗位结果分页"><button :disabled="turn.page<=1 || pageLoading" @click="changePage(turn,turn.page-1)">上一页</button><span>第 <input v-model.number="turn.pageInput" type="number" min="1" :max="turn.totalPages" :disabled="pageLoading" aria-label="跳转页码" @keydown.enter.prevent="changePage(turn,turn.pageInput)"> / {{turn.totalPages}} 页 · 每页 {{turn.pageSize}} 条</span><button class="kb-page-go" :disabled="pageLoading || !turn.pageInput || turn.pageInput<1 || turn.pageInput>turn.totalPages" @click="changePage(turn,turn.pageInput)">跳转</button><button :disabled="turn.page>=turn.totalPages || pageLoading" @click="changePage(turn,turn.page+1)">下一页</button></nav>
    </template>
   </article>
  </div>
  <div v-if="loading" class="kb-thinking" role="status"><span class="kb-thinking-shine" data-text="✦ 正在检索公告和岗位要求，请稍候…">✦ 正在检索公告和岗位要求，请稍候…</span></div>
  <div v-if="error" class="kb-error" role="alert">{{error}}<button @click="refreshStatus">重新检查连接</button></div>
  <form class="kb-composer" @submit.prevent="send()"><textarea v-model="draft" maxlength="1000" rows="2" :disabled="loading" placeholder="例如：我是计算机专业，想找杭州的研发岗，有住宿更好" aria-label="岗位检索问题" @keydown.enter.exact.prevent="send()"></textarea><div><span>Enter 发送 · Shift + Enter 换行</span><button type="submit" :disabled="loading || !draft.trim()">{{loading?'检索中…':'发送 ↑'}}</button></div></form>
 </section>
</template>
<style scoped>
